            updateProgressBar('mengzhixia-affection-bar', 'mengzhixia-affection', 'mengzhixia-affection-desc', SafeGetValue(characterData, '孟知夏.与user的好感度'), 0, 400, 'var(--accent-mengzhixia)');

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

